#!/usr/bin/env bash
# install-status-pipeline.sh: puts the Pipeline page on status.auditisa.com. For the owner to run, on the
# production VPS. GENERATED by deploy/status/build-installer.py: change gen-pipeline.js and rebuild.
#
#   bash install-status-pipeline.sh check                 what would change; changes nothing (the default)
#   bash install-status-pipeline.sh install               backs up, installs, checks, and undoes itself on failure
#   bash install-status-pipeline.sh rollback              back to the page as it was
#   bash install-status-pipeline.sh deploy-key            makes a read-only key for the Odoo repository and prints its PUBLIC half
#
# What it changes, and nothing else:
#   /opt/ea-audit-status/gen-pipeline.js                  new; reads GitHub and the page gen-status.js writes
#   /opt/ea-audit-status/pipeline/                        new; its mirrors and its last reading
#   /etc/systemd/system/ea-audit-status.service.d/pipeline.conf   new; runs it after gen-status.js
#   /etc/systemd/system/ea-audit-status.timer.d/pipeline.conf     new; the timer fires on the minute, within 5 s
#   /var/www/status.auditisa.com/{details.html,en.html,pipeline.json}   new; index.html becomes the new page
#
# gen-status.js, the Next.js services, Apache, DNS and every database are not touched. A failure of the new
# script leaves the old page in place. Backup: /root/status-pipeline-backup-<stamp>.tar.gz, root only.

set -euo pipefail
umask 022

: "${STATUS_PREFIX:=}"
ROOT=$STATUS_PREFIX/opt/ea-audit-status
WWW=$STATUS_PREFIX/var/www/status.auditisa.com
UNITS=$STATUS_PREFIX/etc/systemd/system
BACKUPS=$STATUS_PREFIX/root
KEY=$STATUS_PREFIX/root/.ssh/auditisa_odoo_status_ro
SERVICE=ea-audit-status.service
TIMER=ea-audit-status.timer
GEN=$ROOT/gen-pipeline.js
MARKER='<!-- ea-pipeline-page -->'

log() { printf '[status-pipeline] %s\n' "$*"; }
die() { printf '[status-pipeline] ERROR: %s\n' "$*" >&2; exit 1; }

COMMAND=${1:-check}

need_root() {
  if [ -z "$STATUS_PREFIX" ] && [ "$(id -u)" != 0 ]; then die "run as root"; fi
}

preflight() {
  [ -f "$ROOT/gen-status.js" ] || die "$ROOT/gen-status.js is missing: is this the production VPS?"
  [ -d "$WWW" ] || die "$WWW is missing"
  command -v node >/dev/null || die "node is missing"
  command -v git >/dev/null || die "git is missing"
  command -v curl >/dev/null || die "curl is missing"
}

